package com.guocheng.mediapocket;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import android.graphics.drawable.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
/** TVBox detail/episode routing uses the stable player. Player code is not replaced. */
public final class FusionLibraryActivity extends Activity {
 LinearLayout root,body;TextView status;SharedPreferences prefs;boolean light,dead;int epoch;FusionCatalog.Session session;UiImages images=new UiImages();ExecutorService io=Executors.newSingleThreadExecutor();Future<?> pending;ArrayDeque<Runnable> back=new ArrayDeque<>();JSONObject current;
 interface Work {Runnable run()throws Exception;}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}int ink(){return light?0xff173740:0xfff5fafb;}int muted(){return light?0xff52757c:0xffafcbd2;}int surface(){return light?0xffedf5f5:0xff10343e;}int card(){return light?0xffffffff:0xff19434e;}
 GradientDrawable rounded(int color,int r){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(r));return d;}
 @Override public void onCreate(Bundle saved){prefs=getSharedPreferences("data",0);light=prefs.getString("themeMode","dark").equals("light");getTheme().applyStyle(light?android.R.style.Theme_Material_Light_NoActionBar:android.R.style.Theme_Material_NoActionBar,true);super.onCreate(saved);UiImages.configure(getCacheDir());getWindow().setStatusBarColor(surface());getWindow().setNavigationBarColor(surface());getWindow().getDecorView().setSystemUiVisibility(light?View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR:0);
  root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(surface());root.setPadding(dp(16),0,dp(16),0);setContentView(root);LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.addView(button("‹ 返回",()->onBackPressed()));TextView title=text("影视仓",18);title.setTypeface(null,1);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));header.addView(button("搜索",()->search()));root.addView(header);status=text("",12);status.setTextColor(muted());root.addView(status);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(0,0,0,dp(28));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  work("正在打开影视仓…",()->{session=FusionCatalog.session(this,getIntent().getStringExtra("config"),getIntent().getStringExtra("site"));return ()->{String id=getIntent().getStringExtra("id"),category=getIntent().getStringExtra("category");if(id!=null&&!id.isEmpty()){back.push(()->{if(category!=null&&!category.isEmpty())category(category,1);else home();});detail(id);}else if(category!=null&&!category.isEmpty()){back.push(()->home());category(category,1);}else home();};},()->finish());
 }
 TextView text(String label,int size){TextView t=new TextView(this);t.setText(label);t.setTextSize(size);t.setTextColor(ink());t.setIncludeFontPadding(false);t.setPadding(0,dp(8),0,dp(8));return t;}
 Button button(String label,Runnable action){CinemaButton b=new CinemaButton(this,light);b.setText(label);b.setBackground(rounded(card(),12));b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(card()));b.setOnClickListener(v->action.run());return b;}
 void row(String label,Runnable action){Button b=button(label,action);b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(8);body.addView(b,p);}
 void screen(String label){epoch++;if(pending!=null)pending.cancel(true);body.removeAllViews();status.setText(label);}
 void work(String label,Work task,Runnable retry){int token=++epoch;if(pending!=null)pending.cancel(true);status.setText(label);pending=io.submit(()->{try{Runnable done=task.run();runOnUiThread(()->{if(!dead&&token==epoch){status.setText("");done.run();}});}catch(Exception e){runOnUiThread(()->{if(dead||token!=epoch)return;status.setText("读取失败："+(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage()));row("重试",retry);});}});}
 void push(Runnable destination,Runnable previous){back.push(previous);destination.run();}
 void home(){screen(session.site.optString("name"));work("正在读取分类…",()->{JSONObject response=FusionCatalog.request(this,session,"home","","",1);return ()->{status.setText(session.site.optString("name")+" · "+state());JSONArray cats=response.optJSONArray("class");if(cats!=null)for(int i=0;i<cats.length();i++){JSONObject c=cats.optJSONObject(i);if(c!=null)row(c.optString("type_name","分类"),()->push(()->category(c.optString("type_id"),1),()->home()));}gallery(response.optJSONArray("list"),()->home());};},()->home());}
 String state(){if(CmsApi.MARKER.equals(session.site.optString("api")))return session.site.optString("public.status","此公开源待本机实播验证");return session.site.optString("api").equals("csp_AListSh")?"小雅样本已验证播放":"此线路尚未完成实播验证";}
 void category(String id,int page){screen(session.site.optString("name"));work("正在读取分类 · 第 "+page+" 页…",()->{JSONObject response=FusionCatalog.request(this,session,"category",id,"",page);return ()->{status.setText(session.site.optString("name")+" · 第 "+page+" 页");gallery(response.optJSONArray("list"),()->category(id,page));if(response.optInt("pagecount",page)>page)row("下一页",()->push(()->category(id,page+1),()->category(id,page)));};},()->category(id,page));}
 void search(){if(session==null)return;EditText input=new EditText(this);input.setSingleLine(true);new AlertDialog.Builder(this).setTitle("搜索 "+session.site.optString("name")).setView(input).setPositiveButton("搜索",(d,n)->{String word=input.getText().toString().trim();if(!word.isEmpty())push(()->searchResults(word),()->home());}).setNegativeButton("取消",null).show();}
 void searchResults(String word){screen("搜索："+word);work("正在搜索…",()->{JSONObject r=FusionCatalog.request(this,session,"search",word,"",1);return ()->{status.setText("搜索："+word);gallery(r.optJSONArray("list"),()->searchResults(word));};},()->searchResults(word));}
 void gallery(JSONArray list,Runnable previous){if(list==null||list.length()==0){body.addView(text("此分类暂时没有条目",14));return;}int available=getResources().getDisplayMetrics().widthPixels-dp(32),columns=Math.max(3,Math.min(6,available/dp(140))),width=(available-dp(10)*(columns-1))/columns;LinearLayout line=null;for(int i=0;i<Math.min(list.length(),300);i++){JSONObject v=list.optJSONObject(i);if(v==null||v.optString("vod_id").isEmpty())continue;if(line==null||line.getChildCount()==columns){line=new LinearLayout(this);line.setGravity(Gravity.TOP);body.addView(line);}LinearLayout tile=new LinearLayout(this);tile.setOrientation(1);FrameLayout frame=new FrameLayout(this);frame.setBackground(rounded(card(),10));frame.setClipToOutline(true);tile.addView(frame,new LinearLayout.LayoutParams(width,(int)(width*1.5)));TextView empty=text("影片",12);empty.setGravity(Gravity.CENTER);frame.addView(empty,new FrameLayout.LayoutParams(-1,-1));ImageView pic=new ImageView(this);pic.setScaleType(ImageView.ScaleType.CENTER_CROP);frame.addView(pic,new FrameLayout.LayoutParams(-1,-1));load(pic,v.optString("vod_pic"),width);if(v.optString("vod_pic").isEmpty()){final int token=epoch;FusionArtwork.resolve(this,v,match->runOnUiThread(()->{if(token==epoch&&!dead)load(pic,match.optString("poster"),width);}));}TextView name=text(v.optString("vod_name","影片"),11);name.setLines(2);name.setEllipsize(android.text.TextUtils.TruncateAt.END);name.setGravity(Gravity.CENTER);tile.addView(name);tile.setOnClickListener(w->push(()->detail(v.optString("vod_id")),previous));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(width,-2);p.rightMargin=dp(10);p.bottomMargin=dp(8);line.addView(tile,p);}}
 void load(ImageView v,String url,int width){if(url.isEmpty())return;try{TvPosterImages.load(this,v,TvPosterRules.resolve(session.url,url),width);}catch(Exception ignored){}}
 void detail(String id){screen("影片详情");work("正在读取影片与选集…",()->{JSONObject response=FusionCatalog.request(this,session,"detail",id,"",1);JSONArray list=response.optJSONArray("list");JSONObject m=list==null?null:list.optJSONObject(0);if(m==null)throw new Exception("站点未返回详情");return ()->{current=m;String title=m.optString("vod_name","影片");status.setText(session.site.optString("name"));FrameLayout hero=new FrameLayout(this);hero.setBackground(rounded(card(),12));hero.setClipToOutline(true);ImageView cover=new ImageView(this);cover.setScaleType(ImageView.ScaleType.CENTER_CROP);hero.addView(cover,new FrameLayout.LayoutParams(-1,-1));load(cover,m.optString("vod_pic"),dp(600));final int detailToken=epoch;if(m.optString("vod_pic").isEmpty())FusionArtwork.resolve(this,m,match->runOnUiThread(()->{if(detailToken==epoch&&!dead)load(cover,match.optString("poster"),dp(600));}));body.addView(hero,new LinearLayout.LayoutParams(-1,Math.min(dp(320),(int)(getResources().getDisplayMetrics().widthPixels*.60))));TextView name=text(title,23);name.setTypeface(null,1);body.addView(name);String facts=m.optString("vod_year")+"  "+m.optString("vod_area")+"  "+m.optString("vod_remarks");body.addView(text(facts.trim(),12));String desc=FusionCatalog.plain(m.optString("vod_content"));if(!desc.isEmpty())body.addView(text(desc,13));row("播放来源 · 搜索其他站点",()->{FusionCatalog.Session previous=session;new SourcePickerDialog(this,session,MediaMatchRules.clean(title),(selected,item)->{if(dead)return;back.push(()->{session=previous;detail(id);});session=selected;detail(item.optString("vod_id"));});});row("匹配封面 / 字幕影片身份",()->matchArtwork(m,cover));String actors=m.optString("vod_actor");if(!actors.isEmpty())body.addView(text("演员 · "+actors,12));String[] flags=m.optString("vod_play_from").split("\\$\\$\\$",-1),groups=m.optString("vod_play_url").split("\\$\\$\\$",-1);int count=0;for(int g=0;g<groups.length;g++){String flag=g<flags.length?flags[g]:"线路 "+(g+1);body.addView(text(flag,16));for(String encoded:groups[g].split("#")){if(count++>=1000){body.addView(text("选集较多，仅显示前 1000 项",13));return;}String[] episode=encoded.split("\\$",2);if(episode.length<2||episode[1].isEmpty())continue;row("▶ "+episode[0],()->play(id,title,flag,episode[0],episode[1]));}}if(count==0)body.addView(text("此条目未返回选集",13));};},()->detail(id));}
 void play(String id,String title,String flag,String episode,String value){work("正在获取并检查播放地址…",()->{JSONObject r=FusionCatalog.request(this,session,"player",value,flag,1);TvBoxPlay.Resolved resolved=TvBoxPlay.resolve(this,session,flag,r,40000);JSONObject stream=resolved.stream;stream.put("name",session.site.optString("name"));
   JSONObject meta=FusionCatalog.normalize(session,new JSONArray().put(current),"").optJSONObject(0);String watch="tvbox:"+TvSpiderRules.digest((session.url+"|"+session.site.optString("key")+"|"+id+"|"+episode).getBytes("UTF-8"),"SHA-256");FusionArtwork.fill(meta,FusionArtwork.cached(this,current));meta.put("subtitleEpisode",episode).put("fusion.title",title).put("fusion.flag",flag);meta.put("id",watch).put("name",title+" · "+episode).put("fusion.video",id);return ()->PlaybackCheck.decide(this,session.site.optString("name")+" · "+title+" · "+episode,stream.optString("url"),resolved.via,resolved.check,()->{if(dead)return;status.setText(title+" · "+episode+" · "+resolved.check.summary());Intent in=new Intent(this,PlayerActivity.class);in.putExtra("stream",stream.toString());in.putExtra("sources",new JSONArray().put(stream).toString());in.putExtra("id",watch);in.putExtra("type",meta.optString("fusion.mediaType",FusionPlaybackRules.episode(episode,flag+" "+title).number>0?"series":"movie"));in.putExtra("meta",meta.toString());in.putExtra("addons",prefs.getString("addons","[]"));startActivity(in);});},()->play(id,title,flag,episode,value));}

 void matchArtwork(JSONObject m,ImageView cover){EditText input=new EditText(this);input.setText(MediaMatchRules.clean(m.optString("vod_name")));new AlertDialog.Builder(this).setTitle("搜索影片元数据").setView(input).setPositiveButton("搜索",(d,n)->work("正在匹配影片…",()->{JSONArray results=FusionArtwork.search(input.getText().toString());return ()->{if(results.length()==0){status.setText("未匹配到影片，可改用英文名搜索");return;}String[] labels=new String[results.length()];for(int i=0;i<labels.length;i++){JSONObject v=results.optJSONObject(i);labels[i]=v.optString("name")+" · "+v.optString("releaseInfo")+" · "+v.optString("type");}new AlertDialog.Builder(this).setTitle("确认对应影片").setItems(labels,(x,index)->{JSONObject chosen=results.optJSONObject(index);FusionArtwork.save(this,m,chosen);load(cover,chosen.optString("poster"),dp(600));status.setText("匹配已保存 · 字幕将使用此影片身份");}).show();};},()->matchArtwork(m,cover))).setNegativeButton("取消",null).show();}
 @Override public void onBackPressed(){epoch++;if(pending!=null)pending.cancel(true);if(!back.isEmpty())back.pop().run();else super.onBackPressed();}
 @Override protected void onResume(){PlaybackOrientation.releaseHost(this);super.onResume();}
 @Override public void onDestroy(){dead=true;epoch++;io.shutdownNow();super.onDestroy();}
}
